"""Windows-native composition using generated bytes, never private inputs.

Only receipt/source planning is synthesized. NTFS staging, protected ACL/owner,
held-handle output reads, hash verification and cleanup remain native.
"""
import hashlib
import sys
import threading
from contextlib import contextmanager
from types import SimpleNamespace

import pytest

from cardputer_mcp import private_build_producer as module
from cardputer_mcp.private_build_output import PrivateBuildLogs
from cardputer_mcp.private_input_contract import InputFile
from cardputer_mcp.private_workspace_plan import WorkspacePlan
from cardputer_mcp.private_workspace_windows import materialize_windows_workspace

pytestmark = pytest.mark.skipif(sys.platform != "win32", reason="native Windows required")


@pytest.fixture
def native_fixture(tmp_path, monkeypatch):
    paths = []
    registration = SimpleNamespace(source_commit="a" * 40, recipe_sha256="b" * 64)
    builder = SimpleNamespace(
        settings=SimpleNamespace(
            build_projects={"fixture": SimpleNamespace(private_inputs={"fixture": registration})}
        ),
        process=SimpleNamespace(active=False, uncertain=False, stop_requested=threading.Event()),
        output_uncertain=False,
    )
    plan = dict(project_id="fixture", private_input_id="fixture", build_principal="owner")
    monkeypatch.setattr(module, "_recheck", lambda *_: None)

    @contextmanager
    def stage(*_, **kwargs):
        source_plan = WorkspacePlan("e" * 64, (("source.txt", b"synthetic source"),))
        with materialize_windows_workspace(source_plan, container=tmp_path) as source:
            paths.append(source)
            yield SimpleNamespace(directory=source, composition_identity="e" * 64)

    monkeypatch.setattr(module, "stage_private_build", stage)

    def compile_staged(source, output, logs):
        paths.append(output)
        assert source != output
        assert source.parent == output.parent == tmp_path
        assert (source / "source.txt").read_bytes() == b"synthetic source"
        assert not (output / "source.txt").exists()
        data = b"synthetic firmware"
        (output / "fixture.bin").write_bytes(data)
        return (InputFile("fixture.bin", len(data), hashlib.sha256(data).hexdigest()),)

    return builder, plan, paths, tmp_path, compile_staged


def test_native_capture_and_cleanup(native_fixture):
    builder, plan, paths, container, compile_staged = native_fixture
    producer = module.NativePrivateProducer(builder, container, compile_staged)
    result = producer(plan, PrivateBuildLogs("owner"))
    assert result.files == (("fixture.bin", b"synthetic firmware"),)
    assert len(paths) == 2 and all(not p.exists() for p in paths)
    assert producer.retained is None


@pytest.mark.parametrize("failure", ["hash", "cancel"])
def test_native_capture_failure_cleans(native_fixture, failure):
    builder, plan, paths, container, compile_staged = native_fixture

    def compile_fail(source, output, logs):
        manifest = compile_staged(source, output, logs)
        if failure == "hash":
            (output / "fixture.bin").write_bytes(b"altered")
        else:
            builder.process.stop_requested.set()
        return manifest

    producer = module.NativePrivateProducer(builder, container, compile_fail)
    with pytest.raises(ValueError):
        producer(plan, PrivateBuildLogs("owner"))
    assert len(paths) == 2 and all(not p.exists() for p in paths)


def test_native_uncertain_child_retains_until_reconciled(native_fixture):
    builder, plan, paths, container, compile_staged = native_fixture

    def compile_uncertain(*args):
        manifest = compile_staged(*args)
        builder.process.uncertain = True
        return manifest

    producer = module.NativePrivateProducer(builder, container, compile_uncertain)
    try:
        with pytest.raises(ValueError, match="child_not_joined"):
            producer(plan, PrivateBuildLogs("owner"))
        assert len(paths) == 2 and all(p.exists() for p in paths)
        assert builder.output_uncertain
        with pytest.raises(ValueError, match="child_not_joined"):
            producer.release_after_join()
    finally:
        # Synthetic process state only; no real process is killed or impersonated.
        builder.process.uncertain = False
        producer.release_after_join()
    assert all(not p.exists() for p in paths)
    assert builder.output_uncertain
